package com.example.rokidgeminisecretary;
import android.content.Context;import android.net.*;import java.net.*;import java.util.*;
/** Advertise local Wi-Fi/hotspot addresses, never default cellular/VPN interfaces. */
final class LocalShareNetwork {
 static final class Entry {final String address,label;final int score;Entry(String ip,String label,int score){address=ip;this.label=label;this.score=score;}}
 private static void offer(Map<String,Entry> choices,String ip,String name,boolean wifi,boolean ethernet,boolean vpn,boolean active){int score=LocalShareAddressPolicy.priority(name,wifi,ethernet,vpn);if(score<0||!LocalShareAddressPolicy.valid(ip))return;String label=score>=400?"スマホのテザリング":wifi?"同じWi-Fi":ethernet||score==150?"有線LAN":"Wi-Fi／テザリング";if(active)score+=10;Entry old=choices.get(ip);if(old==null||score>old.score)choices.put(ip,new Entry(ip,label,score));}
 static java.util.List<Entry> addresses(Context context){Map<String,Entry> choices=new LinkedHashMap<>();try{ConnectivityManager cm=(ConnectivityManager)context.getSystemService(Context.CONNECTIVITY_SERVICE);if(cm!=null){Network active=cm.getActiveNetwork();for(Network n:cm.getAllNetworks()){NetworkCapabilities caps=cm.getNetworkCapabilities(n);LinkProperties lp=cm.getLinkProperties(n);if(caps==null||lp==null)continue;boolean wifi=caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI),eth=caps.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET),vpn=caps.hasTransport(NetworkCapabilities.TRANSPORT_VPN);if(!wifi&&!eth||vpn)continue;for(LinkAddress a:lp.getLinkAddresses())if(a.getAddress() instanceof Inet4Address)offer(choices,a.getAddress().getHostAddress(),lp.getInterfaceName(),wifi,eth,vpn,n.equals(active));}}}catch(Exception ignored){}
 try{for(NetworkInterface n:Collections.list(NetworkInterface.getNetworkInterfaces())){if(!n.isUp()||n.isLoopback())continue;for(InetAddress a:Collections.list(n.getInetAddresses()))if(a instanceof Inet4Address)offer(choices,a.getHostAddress(),n.getName(),false,false,false,false);}}catch(Exception ignored){}java.util.List<Entry> result=new ArrayList<>(choices.values());Collections.sort(result,(a,b)->a.score==b.score?a.address.compareTo(b.address):Integer.compare(b.score,a.score));return result;}
 static String address(Context context){java.util.List<Entry> options=addresses(context);return options.isEmpty()?"":options.get(0).address;}
 private LocalShareNetwork(){}
}
